import 'dart:io';\nimport 'package:googleapis/drive/v3.dart' as drive;\nimport 'package:googleapis_auth/googleapis_auth.dart';\nimport 'package:google_sign_in/google_sign_in.dart';\n\nimport '../providers/auth_provider.dart';\n\nclass DriveService {\n  static DriveService? _instance;\n  factory DriveService() => _instance ??= DriveService._();\n  DriveService._();\n\n  drive.DriveApi? _driveApi;\n\n  Future<void> initialize() async {\n    final googleUser = await GoogleSignIn(scopes: [drive.DriveApi.driveScope]).signIn();\n    if (googleUser == null) return;\n\n    final accessToken = (await googleUser.authentication).accessToken;\n    if (accessToken == null) return;\n\n    final credentials = AccessCredentials(\n      AccessToken('Bearer', accessToken, DateTime.now().add(const Duration(hours: 1))),\n      null,\n      [drive.DriveApi.driveScope],\n    );\n\n    final authenticatedClient = await clientViaEphemeralUser(\n      https: true,\n      scopes: [drive.DriveApi.driveScope],\n    ) as AutoRefreshingAuthClient;\n\n    _driveApi = drive.DriveApi(authenticatedClient);\n  }\n\n  Future<String> uploadFile(String name, List<int> bytes, {String? folderId}) async {\n    if (_driveApi == null) await initialize();\n\n    final file = drive.File()\n      ..name = name\n      ..parents = folderId != null ? [folderId] : null;\n\n    final media = drive.Media(Stream.value(bytes), bytes.length);\n\n    final uploadedFile = await _driveApi!.files.create(file, uploadMedia: media);\n    return uploadedFile.id!;\n  }\n\n  Future<List<int>> downloadFile(String fileId) async {\n    if (_driveApi == null) await initialize();\n\n    final file = await _driveApi!.files.get(fileId);\n    if (file == null) throw Exception('File not found');\n\n    final stream = await _driveApi!.files.get(fileId, downloadOptions: drive.DownloadOptions.fullMedia)! as ByteStream;\n    return await stream.toBytes();\n  }\n\n  Future<drive.FileList> listFiles({String? folderId}) async {\n    if (_driveApi == null) await initialize();\n\n    final query = folderId != null ? \"'${folderId}' in parents\" : null;\n    return await _driveApi!.files.list(q: query);\n  }\n}